/**
 * Cálculos relacionados ao período de experiência (CLT Art. 445/451 + Súmula 188 TST).
 */

import type { Contrato } from '../types';

/** Diferença em dias entre uma data ISO e hoje (positivo = no futuro). */
export function diasAteData(dateIso: string | null | undefined): number | null {
  if (!dateIso) return null;
  const target = new Date(dateIso + 'T00:00:00');
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const diffMs = target.getTime() - today.getTime();
  return Math.round(diffMs / (1000 * 60 * 60 * 24));
}

/** Próxima data de fim aplicável: prorrogado se houver, senão inicial. */
export function proximoFimContrato(c: Contrato): string | null {
  if (c.tipo !== 'experiencia') return null;
  return c.data_fim_prorrogado ?? c.data_fim_inicial;
}

/** Status visual baseado em dias restantes. */
export type ProbationAlertLevel = 'safe' | 'd30' | 'd15' | 'd7' | 'overdue';

export function probationAlertLevel(diasRestantes: number | null): ProbationAlertLevel {
  if (diasRestantes === null) return 'safe';
  if (diasRestantes < 0) return 'overdue';
  if (diasRestantes <= 7) return 'd7';
  if (diasRestantes <= 15) return 'd15';
  if (diasRestantes <= 30) return 'd30';
  return 'safe';
}

export const PROBATION_ALERT_COLORS: Record<ProbationAlertLevel, string> = {
  safe: 'bg-blue-100 text-blue-900 border-blue-200',
  d30: 'bg-yellow-100 text-yellow-900 border-yellow-200',
  d15: 'bg-orange-100 text-orange-900 border-orange-200',
  d7: 'bg-red-100 text-red-900 border-red-300',
  overdue: 'bg-red-200 text-red-950 border-red-400',
};

export function probationAlertText(diasRestantes: number | null): string {
  if (diasRestantes === null) return 'Sem data definida';
  if (diasRestantes < 0) return `Vencido há ${Math.abs(diasRestantes)} dias`;
  if (diasRestantes === 0) return 'Encerra hoje';
  if (diasRestantes === 1) return 'Encerra amanhã';
  return `Encerra em ${diasRestantes} dias`;
}

/** Valida se uma data de fim respeita CLT Art. 445 (≤ 90 dias). */
export function validatePrazoExperiencia(
  dataInicio: string,
  dataFim: string,
): { valid: boolean; dias: number; error?: string } {
  const inicio = new Date(dataInicio + 'T00:00:00');
  const fim = new Date(dataFim + 'T00:00:00');
  const dias = Math.round((fim.getTime() - inicio.getTime()) / (1000 * 60 * 60 * 24));

  if (dias <= 0) {
    return { valid: false, dias, error: 'Data de fim deve ser posterior à data de início.' };
  }
  if (dias > 90) {
    return {
      valid: false,
      dias,
      error: `Período de ${dias} dias excede o limite legal de 90 dias (CLT Art. 445, parágrafo único).`,
    };
  }
  return { valid: true, dias };
}

/** Valida se prorrogação é permitida. */
export function validateProrrogacao(
  contrato: Contrato,
): { valid: boolean; error?: string } {
  if (contrato.tipo !== 'experiencia') {
    return { valid: false, error: 'Apenas contratos de experiência podem ser prorrogados.' };
  }
  if (contrato.prorrogacao_count >= 1) {
    return {
      valid: false,
      error:
        'CLT Art. 451 + Súmula 188 TST — apenas uma prorrogação é permitida. Contrato deve ser efetivado ou encerrado.',
    };
  }
  if (!contrato.clausula_prorrogacao_prevista) {
    return {
      valid: false,
      error:
        'O contrato original não previu cláusula de prorrogação. Decisão TRT-3/2015 — prorrogação só se prevista no contrato.',
    };
  }
  return { valid: true };
}

/** Calcula tempo de casa em formato "X anos, Y meses". Null-safe. */
export function tempoDeCasa(dataAdmissao: string | null | undefined): string {
  if (!dataAdmissao || typeof dataAdmissao !== 'string' || dataAdmissao.length < 10) return '—';
  const inicio = new Date(dataAdmissao.slice(0, 10) + 'T00:00:00');
  if (Number.isNaN(inicio.getTime())) return '—';
  const today = new Date();
  let anos = today.getFullYear() - inicio.getFullYear();
  let meses = today.getMonth() - inicio.getMonth();
  if (today.getDate() < inicio.getDate()) meses--;
  if (meses < 0) {
    anos--;
    meses += 12;
  }
  if (anos === 0 && meses === 0) {
    const dias = Math.round((today.getTime() - inicio.getTime()) / (1000 * 60 * 60 * 24));
    return `${dias} dia${dias === 1 ? '' : 's'}`;
  }
  if (anos === 0) return `${meses} ${meses === 1 ? 'mês' : 'meses'}`;
  if (meses === 0) return `${anos} ano${anos === 1 ? '' : 's'}`;
  return `${anos} ano${anos === 1 ? '' : 's'}, ${meses} ${meses === 1 ? 'mês' : 'meses'}`;
}

const filters = useMemo<EmployeeFilters>(
  () => ({
    loja_id: selectedStore?.id ?? null,
    search: search.trim() || undefined,
    status: statusFilter === 'todos' ? null : statusFilter,
    cargo_id: cargoFilter === 'todos' ? null : cargoFilter,
    aniversariantes_mes: aniversariantes ? new Date().getMonth() + 1 : null,
  }),
  [selectedStore?.id, search, statusFilter, cargoFilter, aniversariantes],
);

const { employees, loading, fetchEmployees } = useEmployees(filters);

useEffect(() => {
  setSearch('');
  setStatusFilter('todos');
  setCargoFilter('todos');
  setAniversariantes(false);
}, [selectedStore?.id]);

useMiaFuncionariosActions({
  setSearch,
  setStatusFilter,
  setCargoFilter,
  setAniversariantes,
});

const kpis = useMemo(() => {
  const total = employees.length;
  const ativos = employees.filter((e) => e.status === 'active').length;
  const emExperiencia = employees.filter((e) => e.status === 'probation').length;
  const decisoesPendentes = employees.filter((e) => {
    const dias = diasAteData(e.contrato_data_fim);
    return e.status === 'probation' && dias !== null && dias <= 30;
  }).length;
  return { total, ativos, emExperiencia, decisoesPendentes };
}, [employees]);

const alertasCriticos = useMemo(
  () =>
    employees
      .filter((e) => e.status === 'probation')
      .map((e) => ({ emp: e, dias: diasAteData(e.contrato_data_fim) }))
      .filter((x) => x.dias !== null && x.dias <= 7)
      .sort((a, b) => (a.dias ?? 0) - (b.dias ?? 0)),
  [employees],
);

const empty = !loading && employees.length === 0;
const hasFilters =
  !!search.trim() ||
  statusFilter !== 'todos' ||
  cargoFilter !== 'todos' ||
  aniversariantes;

const today = new Date();
const todayMonth = today.getMonth() + 1;
const todayDay = today.getDate();

// MIA 2.0 Glass-Box — contexto pra MIA entender o domínio DP/RH
useMiaPageContext({
  description: 'Gestão de funcionários CLT (DP/RH): cadastro, cargos, experiência, férias, desligamentos, métodos punitivos, e-Social, organograma, analytics, pesquisa de clima.',
  natural_language_hints: [
    '"experiência" = decisões D-7/D-30 sobre prorrogar ou encerrar período de experiência (90d max)',
    '"férias" = marcação CLT, aprovação master, PDF aviso 35d antes',
    '"punitivos" = advertências + suspensões com PDF',
    '"desligamento" = solicitação gerente → aprovação master',
    '"organograma" = hierarquia visual',
  ].join('\n'),
  capabilities: ['consultar', 'cadastrar', 'editar', 'aprovar férias', 'solicitar desligamento', 'cadastrar punitivo'],
  destructive_actions: ['desligar', 'aprovar_desligamento', 'cadastrar_punitivo'],
  primary_entity: 'employee',
});

return (
  <MommaPageLayout>
    <div
      className="relative z-10 w-full max-w-[1600px] mx-auto space-y-6 px-4 sm:px-6 py-6 animate-in fade-in duration-500"
      data-mia-page="funcionarios"
      data-mia-domain="rh"
    >
      {/* Header refinado: título + breadcrumb-like row de ações */}
      <div className="space-y-4">
        <div className="flex items-center gap-3 min-w-0">
          <div className="hidden md:flex h-12 w-12 rounded-2xl bg-[#57715B]/10 dark:bg-[#E6DCCF]/10 items-center justify-center shrink-0">
            <IdCard className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
          </div>
          <div className="min-w-0 flex-1">
            <h1 className="text-3xl md:text-4xl lg:text-5xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif mb-1 truncate">
              Funcionários
            </h1>
            <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80 truncate">
              {selectedStore
                ? `${selectedStore.shortName} · Quadro CLT`
                : 'Carregando loja...'}
            </p>
          </div>
          {isRhMaster &&<DashboardStoreSelector />}
        </div>

        {/* Action bar: Nova admissão (CTA) + links secundários */}
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div className="flex items-center gap-1 text-sm flex-wrap">
            {[
              { path: '/funcionarios/cargos', label: 'Cargos' },
              { path: '/funcionarios/organograma', label: 'Organograma' },
              { path: '/funcionarios/experiencia', label: 'Experiência' },
              { path: '/funcionarios/ferias', label: 'Férias' },
              { path: '/funcionarios/metodos-punitivos', label: 'Métodos punitivos' },
              { path: '/funcionarios/desligamentos', label: 'Desligamentos' },
              { path: '/funcionarios/esocial', label: 'eSocial' },
              { path: '/funcionarios/pesquisa-clima', label: 'Clima' },
            ].flatMap((link, i, arr) => {
              const items = [
                <button
                  key={link.path}
                  onClick={() => navigate(link.path)}
                  className="px-3 py-1.5 rounded-full text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/10 transition-colors font-medium"
                >
                  {link.label}
                </button>,
              ];
              if (i < arr.length - 1) {
                items.push(
                  <span key={`sep-${link.path}`} className="text-[#8C7B6D]/30">·</span>,
                );
              }
              return items;
            })}
          </div>
          <div className="flex items-center gap-2">
            {isSystemAdmin && (
              <Button
                variant="outline"
                onClick={() => navigate('/funcionarios/analytics')}
                className="rounded-2xl border-[#B49364]/40 text-[#7a5f3a] dark:text-[#C5A065] hover:bg-[#B49364]/10 h-10"
                title="Painel executivo (admin do sistema)"
              >
                <BarChart3 className="h-4 w-4 mr-2" />
                Painel executivo
              </Button>
            )}
            <Button
              onClick={() => navigate('/funcionarios/novo')}
              className="rounded-2xl bg-[#57715B] hover:bg-[#4a6450] text-white h-10 shadow-md shadow-[#57715B]/20"
            >
              <Plus className="h-4 w-4 mr-2" />
              Nova admissão
            </Button>
          </div>
        </div>
      </div>

      {/* Banner crítico — fim de experiência iminente (D-7 ou vencido) */}
      {alertasCriticos.length > 0 && (
        <button
          onClick={() => navigate('/funcionarios/experiencia')}
          className="w-full text-left bg-gradient-to-r from-red-500/10 via-red-500/5 to-transparent border-l-4 border-l-red-500 backdrop-blur-md border border-red-500/20 rounded-[28px] p-5 shadow-md shadow-red-500/10 hover:shadow-lg transition-all group"
        >
          <div className="flex items-start gap-4">
            <div className="h-12 w-12 rounded-2xl bg-red-500/15 flex items-center justify-center shrink-0 animate-pulse">
              <AlertCircle className="h-6 w-6 text-red-700 dark:text-red-300" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="font-bold text-[#2D362E] dark:text-[#E6DCCF] text-base">
                {alertasCriticos.length === 1
                  ? `${alertasCriticos[0].emp.nome_completo} encerra experiência em ${
                      alertasCriticos[0].dias === 0
                        ? 'hoje'
                        : alertasCriticos[0].dias === 1
                        ? '1 dia'
                        : `${alertasCriticos[0].dias} dias`
                    }`
                  : `${alertasCriticos.length} funcionários precisam de decisão urgente`}
              </p>
              <p className="text-sm text-[#8C7B6D] dark:text-[#9BA59C] mt-1">
                Comunique o DP/RH se prorroga ou desliga. Sem decisão, vira contrato indeterminado por inércia (CLT Art. 451).
              </p>
            </div>
            <ArrowRight className="h-5 w-5 text-red-700 dark:text-red-300 shrink-0 mt-1 group-hover:translate-x-1 transition-transform" />
          </div>
        </button>
      )}

      {/* KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <KpiCard label="Headcount" value={loading ? '—' : kpis.total} color="#57715B" />
        <KpiCard label="Ativos" value={loading ? '—' : kpis.ativos} color="#33733F" />
        <KpiCard label="Em experiência" value={loading ? '—' : kpis.emExperiencia} color="#B49364" />
        <KpiCard
          label="Decisões ≤30d"
          value={loading ? '—' : kpis.decisoesPendentes}
          color={kpis.decisoesPendentes > 0 ? '#C04848' : '#8C7B6D'}
          highlight={kpis.decisoesPendentes > 0}
          onClick={
            kpis.decisoesPendentes > 0 ? () => navigate('/funcionarios/experiencia') : undefined
          }
        />
      </div>

