322	function DecisionDialog({
323	  context,
324	  onClose,
325	  onSuccess,
326	}: {
327	  context: DecisionContext;
328	  onClose: () => void;
329	  onSuccess: () => void;
330	}) {
331	  const { employee, contrato, tipo } = context;
332	  const [justificativa, setJustificativa] = useState('');
333	  const [novaDataFim, setNovaDataFim] = useState('');
334	  const [submitting, setSubmitting] = useState(false);
335	
336	  // Validações específicas
337	  const prorrogacaoCheck = useMemo(() => {
338	    if (tipo !== 'prorrogar') return { valid: true };
339	    return validateProrrogacao(contrato);
340	  }, [tipo, contrato]);
341	
342	  const novaDataCheck = useMemo(() => {
343	    if (tipo !== 'prorrogar' || !novaDataFim) return { valid: false, dias: 0 };
344	    return validatePrazoExperiencia(contrato.data_inicio, novaDataFim);
345	  }, [tipo, novaDataFim, contrato.data_inicio]);
346	
347	  const justificativaObrigatoria = tipo !== 'efetivar';
348	  const formValido =
349	    prorrogacaoCheck.valid &&
350	    (tipo !== 'prorrogar' || novaDataCheck.valid) &&
351	    (!justificativaObrigatoria || justificativa.trim().length > 0);
352	
353	  // Data de fim = data_inicio + 89 dias (dia de início conta como dia 1, total 90 dias CLT Art. 445)
354	  useEffect(() => {
355	    if (tipo === 'prorrogar') {
356	      const maxFim = new Date(contrato.data_inicio + 'T00:00:00');
357	      maxFim.setDate(maxFim.getDate() + 89);
358	      setNovaDataFim(maxFim.toISOString().slice(0, 10));
359	    }
360	  }, [tipo, contrato.data_inicio]);
361	
362	  const handleSubmit = async () => {
363	    if (!formValido) return;
364	    setSubmitting(true);
365	    try {
366	      // 1) Insere registro em experiencia_decisoes
367	      const { error: errDecisao } = await supabase
368	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
369	        .from('experiencia_decisoes' as any)
370	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
371	        .insert({
372	          contrato_id: contrato.id,
373	          employee_id: employee.id,
374	          tipo,
