376	          justificativa: justificativa.trim() || null,
377	          metadata: tipo === 'prorrogar' ? { nova_data_fim: novaDataFim } : null,
378	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
379	        } as any);
380	      if (errDecisao) throw errDecisao;
381	
382	      // 2) Atualiza contrato + employee conforme decisão
383	      if (tipo === 'efetivar') {
384	        await supabase
385	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
386	          .from('contratos' as any)
387	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
388	          .update({ ativo: false } as any)
389	          .eq('id', contrato.id);
390	        await supabase
391	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
392	          .from('contratos' as any)
393	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
394	          .insert({
395	            employee_id: employee.id,
396	            tipo: 'indeterminado',
397	            data_inicio: new Date().toISOString().slice(0, 10),
398	            ativo: true,
399	          } as any);
400	        await supabase
401	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
402	          .from('employees' as any)
403	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
404	          .update({ status: 'active' } as any)
405	          .eq('id', employee.id);
406	      } else if (tipo === 'prorrogar') {
407	        await supabase
408	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
409	          .from('contratos' as any)
410	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
411	          .update({
412	            data_fim_prorrogado: novaDataFim,
413	            prorrogacao_count: (contrato.prorrogacao_count ?? 0) + 1,
414	          } as any)
415	          .eq('id', contrato.id);
416	      } else if (tipo === 'encerrar') {
417	        const hoje = new Date().toISOString().slice(0, 10);
418	        await supabase
419	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
420	          .from('contratos' as any)
421	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
422	          .update({ ativo: false } as any)
423	          .eq('id', contrato.id);
