452	        variant: 'destructive',
453	      });
454	    } finally {
455	      setSubmitting(false);
456	    }
457	  };
458	
459	  const dias = diasAteData(
460	    contrato.data_fim_prorrogado ?? contrato.data_fim_inicial,
461	  );
462	
463	  // Cálculos das duas experiências
