/* ── utils ── */
const parseDateLocal = (s: string): Date => {
  if (!s) return new Date(NaN);
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m-1, Number(String(d).slice(0,2)));
};
const isWithinRange = (date: Date, from?: Date, to?: Date) => {
  if (!from || !to) return true;
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  return d >= new Date(from.getFullYear(), from.getMonth(), from.getDate())
      && d <= new Date(to.getFullYear(),   to.getMonth(),   to.getDate());
};

