const handleSalvarAvulso = async () => {
  if (!novoAvulso.nome.trim()){ alert('Informe o nome'); return; }
  if (!novoAvulso.valorDiaria.trim()){ alert('Informe o valor'); return; }
  if (!novoAvulso.workDate.trim()){ alert('Informe a data'); return; }
  const val = parseFloat(novoAvulso.valorDiaria);
  if (isNaN(val)||val<=0){ alert('Valor inválido'); return; }
  if (savingAvulso) return;
  setSavingAvulso(true);
  try {
    const {data:{user}} = await supabase.auth.getUser();
    const {error} = await supabase.from('freelancer_avulso_work_days').insert({ nome:novoAvulso.nome.trim(), valor_diaria:val, work_date:novoAvulso.workDate, loja_id:novoAvulso.lojaId?Number(novoAvulso.lojaId):null, local_tipo:novoAvulso.localTipo, evento_nome:novoAvulso.eventoNome||null, setor:novoAvulso.setor||null, observacao:novoAvulso.observacao||null, created_by:user?.id||null });
    if (error) throw error;
    setIsAvulsoDialogOpen(false);
    setNovoAvulso({nome:'',valorDiaria:'',workDate:'',lojaId:'',localTipo:'loja',eventoNome:'',setor:'',observacao:''});
    await fetchAvulsos();
  } catch(err){ console.error(err); alert('Erro ao registrar avulso: '+((err as Error)?.message||err)); }
  finally { setSavingAvulso(false); }
};

